CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] = "Pro tento obrázek chybí popis."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Zasedající shromáždění, pohled ze zadní části sálu přes hlavy posluchačů. Vpředu sedí delegáti kolem dlouhého stolu zakrytého červenou látkou, na pódiu pokrytém kobercem, a u každého místa leží bílý papír. V čele stolu stojí muž v bílém rouchu a s bílou pokrývkou hlavy a oslovuje sál, po jeho boku stojí muž s tmavým plnovousem. Posluchači na ně hledí z řad dřevěných židlí, kde se mísí turbany, čepičky i holé hlavy. Další diváci přihlížejí mezi světlými sloupy podél pravé stěny."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Obří ruské kolo vystupuje z horního okraje obrazu vpravo, po jeho obvodu visí uzavřené kabiny pro cestující. Jeho spodek sestupuje za velký oblouk ze zeleného nýtovaného železa, který se klene nad světlou stěnou s nápisem FERRIS WHEEL. Návštěvníci výstavy přecházejí širokou prašnou promenádu pod ním: ženy v dlouhých šatech, muži v kabátech, buřincích a cylindrech. Nízké výstavní budovy s malovanými cedulemi lemují cestu vlevo, kde v dálce pod světle modrou oblohou vyrůstá bílá hala s kupolí."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "První kroky závodu: čtyři běžci se vrhají vpřed od startovní čáry, se skloněnými hlavami, po tmavé dráze, která se line přes popředí. Za nimi vlevo stojí startér v dlouhém bílém plášti, s pistolí zdviženou a ještě kouřící. Celé pozadí vyplňují zaplněné tribuny, dav je naznačen jako skvrnky barev. Bílé žebříkové tribuny a vysoké sloupky lemují dráhu vpravo a za nimi se rozprostírá zeleň vnitřního pole."
